//! Render a list as one newline-terminated file body.

/// Render a list as one item per line, newline-terminated, or empty for an empty list.
pub(crate) fn lines(v: &[String]) -> String {
    if v.is_empty() {
        String::new()
    } else {
        let mut s = v.join("\n");
        s.push('\n');
        s
    }
}
